class Interpolation:
    def __init__(self):
        pass

    @staticmethod
    def _find_interval_index(x, xi):
        for i in range(len(x) - 1):
            if x[i] <= xi <= x[i + 1]:
                return i
        return None

    @staticmethod
    def _linear_interpolate(y, x, i, xi):
        return y[i] + (y[i + 1] - y[i]) * (xi - x[i]) / (x[i + 1] - x[i])

    @staticmethod
    def _bilinear_interpolate(z, x, y, i, j, xi, yi):
        z00 = z[i][j]
        z01 = z[i][j + 1]
        z10 = z[i + 1][j]
        z11 = z[i + 1][j + 1]

        numerator = (z00 * (x[i + 1] - xi) * (y[j + 1] - yi) +
                     z10 * (xi - x[i]) * (y[j + 1] - yi) +
                     z01 * (x[i + 1] - xi) * (yi - y[j]) +
                     z11 * (xi - x[i]) * (yi - y[j]))
        denominator = (x[i + 1] - x[i]) * (y[j + 1] - y[j])
        return numerator / denominator

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        y_interp = []
        for xi in x_interp:
            i = Interpolation._find_interval_index(x, xi)
            if i is not None:
                yi = Interpolation._linear_interpolate(y, x, i, xi)
                y_interp.append(yi)
        return y_interp

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        z_interp = []
        for xi, yi in zip(x_interp, y_interp):
            i = Interpolation._find_interval_index(x, xi)
            j = Interpolation._find_interval_index(y, yi)
            if i is not None and j is not None:
                zi = Interpolation._bilinear_interpolate(z, x, y, i, j, xi, yi)
                z_interp.append(zi)
        return z_interp
